SELECT dim, value, COUNT(DISTINCT deeper_node) AS deeper_nodes FROM (
SELECT 'Profit_Center' AS dim, TRIM(c.ProfitCentre) AS value, h2.node AS deeper_node FROM config_csv c JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` h1 ON h1.dimension_name = 'Profit_Center' AND h1.parent = TRIM(c.ProfitCentre) AND (CASE WHEN NULLIF(TRIM(c.ProfitCentreHierarchyName), '') IS NULL THEN h1.is_primary = TRUE ELSE h1.hierarchy_name = NULLIF(TRIM(c.ProfitCentreHierarchyName), '') END) JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` h2 ON h2.dimension_name = 'Profit_Center' AND h2.parent = h1.node AND (CASE WHEN NULLIF(TRIM(c.ProfitCentreHierarchyName), '') IS NULL THEN h2.is_primary = TRUE ELSE h2.hierarchy_name = NULLIF(TRIM(c.ProfitCentreHierarchyName), '') END) LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` h3 ON h3.dimension_name = 'Profit_Center' AND h3.parent = TRIM(c.ProfitCentre) AND h3.node = h2.node AND (CASE WHEN NULLIF(TRIM(c.ProfitCentreHierarchyName), '') IS NULL THEN h3.is_primary = TRUE ELSE h3.hierarchy_name = NULLIF(TRIM(c.ProfitCentreHierarchyName), '') END) WHERE (c.Formula IS NULL OR TRIM(c.Formula) = '') AND NOT (c.ProfitCentre IS NULL OR TRIM(c.ProfitCentre) = '' OR UPPER(TRIM(c.ProfitCentre)) IN ('ALL', 'NA')) AND h3.node IS NULL
UNION ALL
SELECT 'Account' AS dim, TRIM(c.Account) AS value, h2.node AS deeper_node FROM config_csv c JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` h1 ON h1.dimension_name = 'Account' AND h1.parent = TRIM(c.Account) AND (CASE WHEN NULLIF(TRIM(c.AccountHierarchy), '') IS NULL THEN h1.is_primary = TRUE ELSE h1.hierarchy_name = NULLIF(TRIM(c.AccountHierarchy), '') END) JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` h2 ON h2.dimension_name = 'Account' AND h2.parent = h1.node AND (CASE WHEN NULLIF(TRIM(c.AccountHierarchy), '') IS NULL THEN h2.is_primary = TRUE ELSE h2.hierarchy_name = NULLIF(TRIM(c.AccountHierarchy), '') END) LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` h3 ON h3.dimension_name = 'Account' AND h3.parent = TRIM(c.Account) AND h3.node = h2.node AND (CASE WHEN NULLIF(TRIM(c.AccountHierarchy), '') IS NULL THEN h3.is_primary = TRUE ELSE h3.hierarchy_name = NULLIF(TRIM(c.AccountHierarchy), '') END) WHERE (c.Formula IS NULL OR TRIM(c.Formula) = '') AND NOT (c.Account IS NULL OR TRIM(c.Account) = '' OR UPPER(TRIM(c.Account)) IN ('ALL', 'NA')) AND h3.node IS NULL
UNION ALL
SELECT 'Company_Code' AS dim, TRIM(c.CompanyCode) AS value, h2.node AS deeper_node FROM config_csv c JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` h1 ON h1.dimension_name = 'Company_Code' AND h1.parent = TRIM(c.CompanyCode) AND (h1.is_primary = TRUE) JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` h2 ON h2.dimension_name = 'Company_Code' AND h2.parent = h1.node AND (h2.is_primary = TRUE) LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` h3 ON h3.dimension_name = 'Company_Code' AND h3.parent = TRIM(c.CompanyCode) AND h3.node = h2.node AND (h3.is_primary = TRUE) WHERE (c.Formula IS NULL OR TRIM(c.Formula) = '') AND NOT (c.CompanyCode IS NULL OR TRIM(c.CompanyCode) = '' OR UPPER(TRIM(c.CompanyCode)) IN ('ALL', 'NA')) AND h3.node IS NULL
UNION ALL
SELECT 'Market' AS dim, TRIM(c.Market) AS value, h2.node AS deeper_node FROM config_csv c JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` h1 ON h1.dimension_name = 'Market' AND h1.parent = TRIM(c.Market) AND (h1.is_primary = TRUE) JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` h2 ON h2.dimension_name = 'Market' AND h2.parent = h1.node AND (h2.is_primary = TRUE) LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` h3 ON h3.dimension_name = 'Market' AND h3.parent = TRIM(c.Market) AND h3.node = h2.node AND (h3.is_primary = TRUE) WHERE (c.Formula IS NULL OR TRIM(c.Formula) = '') AND NOT (c.Market IS NULL OR TRIM(c.Market) = '' OR UPPER(TRIM(c.Market)) IN ('ALL', 'NA')) AND h3.node IS NULL
) GROUP BY dim, value ORDER BY dim, value LIMIT 50;
